for _, old in ipairs(SoundService:GetChildren()) do
    if old:IsA("Sound") and string.find(old.Name, "^NIER_UI_Sfx_") then
        pcall(function()
            old:Stop()
            old:Destroy()
        end)
    end
end

local function findFn(name)
    local ok, value = pcall(function()
        return _G and _G[name] or nil
    end)
    if ok and type(value) == "function" then
        return value
    end

    ok, value = pcall(function()
        return getfenv and getfenv(0) and getfenv(0)[name] or nil
    end)
    if ok and type(value) == "function" then
        return value
    end

    local gg
    ok, gg = pcall(function()
        return _G and _G.getgenv or (getfenv and getfenv(0) and getfenv(0).getgenv)
    end)
    if ok and type(gg) == "function" then
        local envOk, env = pcall(gg)
        if envOk and type(env) == "table" and type(env[name]) == "function" then
            return env[name]
        end
    end
    return nil
end

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64Map = {}
for i = 1, #B64 do
    B64Map[string.byte(B64, i)] = i - 1
end
local function decodeBase64(text)
    text = string.gsub(text, "%s", "")
    local out, n = {}, 0
    local byte, char, floor = string.byte, string.char, math.floor
    for i = 1, #text, 4 do
        local a, b, c, d = byte(text, i, i + 3)
        local x = (B64Map[a] or 0) * 262144 + (B64Map[b] or 0) * 4096 + (B64Map[c] or 0) * 64 + (B64Map[d] or 0)
        local b1, b2, b3 = floor(x / 65536), floor(x / 256) % 256, x % 256
        n += 1
        if c == 61 then
            out[n] = char(b1)
        elseif d == 61 then
            out[n] = char(b1, b2)
        else
            out[n] = char(b1, b2, b3)
        end
    end
    return table.concat(out)
end

local writeFn, readFn, isFileFn, assetFn
local apiChecked, apiOk = false, false
local function checkApi()
    if apiChecked then
        return apiOk
    end
    apiChecked = true
    writeFn = findFn("writefile")
    readFn = findFn("readfile")
    isFileFn = findFn("isfile")
    assetFn = findFn("getcustomasset") or findFn("getsynasset")
    apiOk = writeFn ~= nil and assetFn ~= nil
    return apiOk
end

local sfxBase
local refreshFiles = false
local function resolveBase()
    if sfxBase then
        return sfxBase
    end
    sfxBase = "NIER_UI_"
    local makeFolder, isFolder = findFn("makefolder"), findFn("isfolder")
    if makeFolder then
        local folderReady = false
        if isFolder then
            local okI, exists = pcall(isFolder, SFX_FOLDER)
            folderReady = okI and exists == true
        end
        if folderReady or pcall(makeFolder, SFX_FOLDER) then
            sfxBase = SFX_FOLDER .. "/"
        end
    end

    local marker = sfxBase .. "_version.txt"
    local current
    if isFileFn and readFn then
        local okF, exists = pcall(isFileFn, marker)
        if okF and exists then
            local okR, content = pcall(readFn, marker)
            current = okR and content or nil
        end
    end
    if current ~= SFX_VERSION then
        refreshFiles = true
        pcall(writeFn, marker, SFX_VERSION)
    end
    return sfxBase
end

local function ensureFile(name, entry)
    local path = resolveBase() .. entry.file
    local keep = false
    if isFileFn and not refreshFiles then
        local okF, exists = pcall(isFileFn, path)
        if okF and exists then
            if readFn then
                local okR, content = pcall(readFn, path)
                keep = okR and type(content) == "string" and #content > 256
            else
                keep = true
            end
        end
    end
    if not keep then
        writeFn(path, decodeBase64(SfxData[name]))
    end
    return path
end

local ContentProvider = game:GetService("ContentProvider")

function Library:SetSoundEnabled(state)
    Library.SoundEnabled = state == true
end
function Library:SetSoundVolume(value)
    Library.SoundVolume = math.clamp(tonumber(value) or 1, 0, 1)
end

local touchOnly = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
Library._onNew = function(inst, class, props)
    if class == "ImageButton" then
        if props.Name ~= "SettingsGearBtn" then
            return
        end
    elseif class == "TextButton" then
        if (tonumber(props.ZIndex) or 0) >= 5 then
            return
        end
    else
        return
    end
    if not touchOnly then
        inst.MouseEnter:Connect(function()
            Library._sfx("hover")
        end)
    end
    inst.MouseButton1Click:Connect(function()

        if not inst:GetAttribute("NoSelectSfx") then
            Library._sfx("select")
        end
    end)
end

Sfx.slider.file = "slider_video_tick.ogg"

local VOICES = { select = 2, hover = 3, toggleOn = 2, toggleOff = 2, notify = 1, slider = 4 }

local DROP_WHILE_LOADING = { hover = true, slider = true }
local pools, building = {}, {}
local transientAssetIds = {}

local function getCachedVoices(name, desired)
    local list = {}
    for _, sound in ipairs(SoundService:GetChildren()) do
        if sound:IsA("Sound")
        and sound.Parent == SoundService
        and sound:GetAttribute("NIER_UI_SfxCacheVersion") == SFX_VERSION
        and sound:GetAttribute("NIER_UI_SfxName") == name then
            list[#list + 1] = sound
        end
    end

    table.sort(list, function(a, b)
        return (tonumber(a:GetAttribute("NIER_UI_SfxVoice")) or math.huge)
        < (tonumber(b:GetAttribute("NIER_UI_SfxVoice")) or math.huge)
    end)

    while #list > desired do
        local extra = table.remove(list)
        pcall(function()
            extra:Stop()
            extra:Destroy()
        end)
    end
    for i, sound in ipairs(list) do
        sound.Name = "NIER_UI_Sfx_" .. name
        sound:SetAttribute("NIER_UI_SfxVoice", i)
        sound.Volume = 0
    end
    return list
end

local function buildPool(name)
    local entry = Sfx[name]
    if not entry or entry.failed then
        return nil
    end
    if pools[name] then
        return pools[name]
    end
    if building[name] then
        return nil
    end

    local desired = VOICES[name] or 1
    local list = getCachedVoices(name, desired)
    if #list >= desired then
        pools[name] = { voices = list, nextVoice = 1 }
        return pools[name]
    end

    if not checkApi() then
        entry.failed = true
        return nil
    end
    if not SfxData[name] then
        return nil
    end

    building[name] = true
    local created = {}
    local ok = pcall(function()
        local assetId = assetFn(ensureFile(name, entry))
        if type(assetId) ~= "string" or assetId == "" then
            error("custom asset function returned no asset id")
        end
        for i = #list + 1, desired do
            local sound = Instance.new("Sound")
            sound.Name = "NIER_UI_Sfx_" .. name
            sound.Volume = 0
            sound.SoundId = assetId
            sound:SetAttribute("NIER_UI_SfxCacheVersion", SFX_VERSION)
            sound:SetAttribute("NIER_UI_SfxName", name)
            sound:SetAttribute("NIER_UI_SfxVoice", i)
            sound.Parent = SoundService
            list[i] = sound
            created[#created + 1] = sound
        end
    end)
    building[name] = nil

    if not ok or #list < desired then
        for _, sound in ipairs(created) do
            pcall(function()
                sound:Stop()
                sound:Destroy()
            end)
        end
        entry.failed = true
        return nil
    end

    pools[name] = { voices = list, nextVoice = 1 }
    return pools[name]
end

local function playNow(voice, entry, pitch)
    if not voice or not voice.Parent then
        return
    end
    voice.Volume = entry.gain * math.clamp(tonumber(Library.SoundVolume) or 1, 0, 1)
    voice.PlaybackSpeed = pitch or 1
    voice.TimePosition = 0
    voice:Play()
end

local function playTransient(name, entry, pitch)
    local assetId = transientAssetIds[name]
    if not assetId then
        if not checkApi() or not SfxData[name] then
            entry.failed = true
            return
        end
        local ok, result = pcall(function()
            return assetFn(ensureFile(name, entry))
        end)
        if not ok or type(result) ~= "string" or result == "" then
            entry.failed = true
            return
        end
        assetId = result
        transientAssetIds[name] = assetId
    end

    local sound = Instance.new("Sound")
    sound.Name = "NIER_UI_Sfx_Transient_" .. name
    sound.SoundId = assetId
    sound.Volume = 0
    sound.PlaybackSpeed = pitch or 1
    sound.Looped = false
    sound.Parent = SoundService

    local cleaned = false
    local function cleanup()
        if cleaned then
            return
        end
        cleaned = true
        pcall(function()
            sound:Stop()
            sound:Destroy()
        end)
    end
    sound.Ended:Connect(cleanup)

    task.spawn(function()

        task.spawn(function()
            pcall(function()
                ContentProvider:PreloadAsync({ sound })
            end)
        end)

        local started = os.clock()
        while sound.Parent and not sound.IsLoaded and os.clock() - started < 3 do
            task.wait(0.03)
        end

        if not sound.Parent then
            return
        end
        if not sound.IsLoaded or not Library.SoundEnabled then
            cleanup()
            return
        end

        sound.Volume = entry.gain * math.clamp(tonumber(Library.SoundVolume) or 1, 0, 1)
        sound.TimePosition = 0
        sound:Play()

        local duration = tonumber(sound.TimeLength) or 0
        task.delay(math.max(duration / math.max(sound.PlaybackSpeed, 0.05) + 2, 5), cleanup)
    end)
end

function Library._sfx(name, pitch)
    if not Library.SoundEnabled then
        return
    end
    local entry = Sfx[name]
    if not entry or entry.failed then
        return
    end

    local now = os.clock()
    if now - (entry.last or -1) < entry.gap then
        return
    end

    if name == "open" or name == "close" then
        entry.last = now
        playTransient(name, entry, pitch)
        return
    end

    local pool = pools[name] or buildPool(name)
    if not pool or #pool.voices == 0 then
        return
    end

    local index = pool.nextVoice
    local voice = pool.voices[index]
    pool.nextVoice = index % #pool.voices + 1
    entry.last = now

    if name == "slider" then
        pitch = 1
    end

    if voice.IsLoaded then
        playNow(voice, entry, pitch)
    elseif not DROP_WHILE_LOADING[name] then
        task.spawn(function()
            local started = os.clock()
            while voice.Parent and not voice.IsLoaded and os.clock() - started < 3 do
                task.wait(0.03)
            end
            if voice.Parent and voice.IsLoaded and Library.SoundEnabled then
                playNow(voice, entry, pitch)
            end
        end)
    end
end

local reloadGeneration = 0

function Library._reloadAllSfx()
    reloadGeneration += 1
    local myGeneration = reloadGeneration

    for _, old in ipairs(SoundService:GetChildren()) do
        if old:IsA("Sound") and string.find(old.Name, "^NIER_UI_Sfx_") then
            pcall(function()
                old:Stop()
                old:Destroy()
            end)
        end
    end

    pools = {}
    building = {}
    transientAssetIds = {}
    for _, entry in pairs(Sfx) do
        entry.failed = nil
        entry.last = nil
    end

    local allVoices = {}
    local order = { "open", "close", "slider", "select", "hover", "toggleOn", "toggleOff", "notify" }

    for _, name in ipairs(order) do
        if myGeneration ~= reloadGeneration then
            return
        end

        if name == "open" or name == "close" then
            local entry = Sfx[name]
            if entry and checkApi() and SfxData[name] then
                local okAsset, assetId = pcall(function()
                    return assetFn(ensureFile(name, entry))
                end)
                if okAsset and type(assetId) == "string" and assetId ~= "" then
                    transientAssetIds[name] = assetId
                    local preloadSound = Instance.new("Sound")
                    preloadSound.Name = "NIER_UI_Sfx_Preload_" .. name
                    preloadSound.SoundId = assetId
                    preloadSound.Volume = 0
                    preloadSound.Looped = false
                    preloadSound.Parent = SoundService
                    allVoices[#allVoices + 1] = preloadSound
                end
            end
        else
            local pool = buildPool(name)
            if pool then
                for _, voice in ipairs(pool.voices) do
                    allVoices[#allVoices + 1] = voice
                end
            end
        end
    end

    task.spawn(function()
        if myGeneration ~= reloadGeneration then
            return
        end
        if #allVoices > 0 then
            pcall(function()
                ContentProvider:PreloadAsync(allVoices)
            end)
        end
        for _, sound in ipairs(allVoices) do
            if sound and sound.Parent and string.find(sound.Name, "^NIER_UI_Sfx_Preload_") then
                pcall(function()
                    sound:Destroy()
                end)
            end
        end
    end)
end
end
